import { axiosClient } from "../../shared/api/axiosClient";
import { getAxiosErrorMessage, getAxiosErrorStatus } from "../../shared/api/axiosError";

function unwrap(res) {
  const data = res?.data;
  if (!data?.success) throw new Error(data?.message || "Request failed");
  return data;
}

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

function toPercent(value) {
  return Math.max(0, Math.min(100, toNumber(value)));
}

function attendanceError(err, fallback) {
  const status = getAxiosErrorStatus(err);
  if (status === 401) return "Please log in as a trainer to view attendance.";
  if (status === 403) return "You can view attendance only for your own courses and sessions.";
  if (status === 404) return "Attendance report is not available yet.";
  if (status >= 500) return "Attendance service is unavailable. Please try again later.";
  return getAxiosErrorMessage(err, fallback);
}

function normalizeCourseStudent(dto, totalSessionsFallback = 0) {
  const raw = dto || {};
  const presentCount = toNumber(raw.presentCount ?? raw.present);
  const lateCount = toNumber(raw.lateCount ?? raw.late);
  const absentCount = toNumber(raw.absentCount ?? raw.absent);
  const attendedCount = toNumber(raw.attendedCount ?? presentCount + lateCount);

  return {
    studentId: String(raw.studentId || raw.id || raw._id || raw.userId || ""),
    fullName: raw.fullName || raw.name || raw.studentName || "Student",
    email: raw.email || raw.emailAddress || raw.EMAIL_ADDRESS || "",
    presentCount,
    lateCount,
    absentCount,
    attendedCount,
    totalSessions: toNumber(raw.totalSessions ?? totalSessionsFallback),
    attendancePercentage: toPercent(raw.attendancePercentage ?? raw.attendancePercent),
    eligibilityStatus: raw.eligibilityStatus || raw.certificateEligibility || "Preview only",
    raw,
  };
}

function normalizeSessionStudent(dto) {
  const raw = dto || {};
  return {
    studentId: String(raw.studentId || raw.id || raw._id || raw.userId || ""),
    fullName: raw.fullName || raw.name || raw.studentName || "Student",
    email: raw.email || raw.emailAddress || raw.EMAIL_ADDRESS || "",
    status: String(raw.status || raw.attendanceStatus || "absent").toLowerCase(),
    firstJoinedAt: raw.firstJoinedAt || raw.first_joined_at || "",
    lastJoinedAt: raw.lastJoinedAt || raw.last_joined_at || "",
    joinCount: toNumber(raw.joinCount ?? raw.joins),
    raw,
  };
}

function normalizeSessionRow(dto) {
  const raw = dto || {};
  const presentCount = toNumber(raw.presentCount ?? raw.present);
  const lateCount = toNumber(raw.lateCount ?? raw.late);
  const absentCount = toNumber(raw.absentCount ?? raw.absent);
  const totalStudents = toNumber(raw.totalStudents ?? raw.studentsCount);

  return {
    sessionId: String(raw.sessionId || raw.id || raw._id || ""),
    occurrenceId: String(raw.occurrenceId || raw.occurrence?._id || raw.occurrence?.id || ""),
    sessionTitle: raw.sessionTitle || raw.title || raw.classTitle || "Session",
    occurrenceDate: raw.occurrenceDate || raw.date || raw.sessionDate || "",
    startsAt: raw.startsAt || raw.startTime || raw.startedAt || "",
    endsAt: raw.endsAt || raw.endTime || raw.endedAt || "",
    presentCount,
    lateCount,
    absentCount,
    totalStudents,
    attendancePercentage: toPercent(raw.attendancePercentage ?? raw.attendancePercent),
    raw,
  };
}

function normalizeCourseSummary(payload) {
  const source = payload?.data || payload || {};
  const totalSessions = toNumber(source.totalSessions);
  const rawStudents = Array.isArray(source.students) ? source.students : [];
  const rawSessions = Array.isArray(source.sessions) ? source.sessions : [];

  return {
    courseId: String(source.courseId || source.course?._id || source.course?.id || ""),
    courseTitle: source.courseTitle || source.course?.title || "Course attendance",
    trainerId: String(source.trainerId || source.trainer?._id || source.trainer?.id || ""),
    totalStudents: toNumber(source.totalStudents),
    totalSessions,
    completedSessions: toNumber(source.completedSessions),
    presentCount: toNumber(source.presentCount),
    lateCount: toNumber(source.lateCount),
    absentCount: toNumber(source.absentCount),
    attendedCount: toNumber(source.attendedCount),
    averageAttendancePercentage: toPercent(
      source.averageAttendancePercentage ?? source.attendancePercentage
    ),
    students: rawStudents.map((student) => normalizeCourseStudent(student, totalSessions)),
    sessions: rawSessions.map(normalizeSessionRow),
    raw: source,
  };
}

function normalizeSessionAttendance(payload) {
  const source = payload?.data || payload || {};
  const row = normalizeSessionRow(source);
  const rawStudents = Array.isArray(source.students) ? source.students : [];

  return {
    ...row,
    attendedCount: toNumber(source.attendedCount ?? row.presentCount + row.lateCount),
    students: rawStudents.map(normalizeSessionStudent),
    raw: source,
  };
}

export async function getTrainerCourseAttendanceSummary(courseId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/courses/${encodeURIComponent(courseId)}/attendance-summary`
    );
    return normalizeCourseSummary(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load course attendance summary."));
  }
}

export async function getTrainerCourseStudentAttendance(courseId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/courses/${encodeURIComponent(courseId)}/student-attendance`
    );
    return normalizeCourseSummary(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load student-wise attendance."));
  }
}

export async function getTrainerSessionAttendance(sessionId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/sessions/${encodeURIComponent(sessionId)}/attendance`
    );
    return normalizeSessionAttendance(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load session attendance details."));
  }
}
